PRAGMA journal_mode=WAL;
PRAGMA synchronous=FULL;
CREATE TABLE IF NOT EXISTS metadata(key TEXT PRIMARY KEY,value TEXT NOT NULL,updated_at REAL NOT NULL);
CREATE TABLE IF NOT EXISTS receipts(seq INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT UNIQUE NOT NULL,kind TEXT NOT NULL,state TEXT NOT NULL,payload_json TEXT NOT NULL,previous_digest TEXT,digest TEXT NOT NULL,path TEXT NOT NULL,created_at REAL NOT NULL);
CREATE TABLE IF NOT EXISTS estates(id TEXT PRIMARY KEY,payload_json TEXT NOT NULL,digest TEXT NOT NULL,path TEXT NOT NULL,created_at REAL NOT NULL);
CREATE TABLE IF NOT EXISTS bfp_builds(id TEXT PRIMARY KEY,path TEXT NOT NULL,digest TEXT NOT NULL,manifest_json TEXT NOT NULL,state TEXT NOT NULL,created_at REAL NOT NULL);
CREATE TABLE IF NOT EXISTS cutovers(id TEXT PRIMARY KEY,state TEXT NOT NULL,proof_json TEXT NOT NULL,digest TEXT NOT NULL,path TEXT NOT NULL,created_at REAL NOT NULL);
CREATE TABLE IF NOT EXISTS outcomes(id TEXT PRIMARY KEY,cutover_id TEXT NOT NULL,payload_json TEXT NOT NULL,digest TEXT NOT NULL,created_at REAL NOT NULL);
CREATE TABLE IF NOT EXISTS resources(id TEXT PRIMARY KEY,provider TEXT NOT NULL,kind TEXT NOT NULL,state TEXT NOT NULL,capabilities_json TEXT NOT NULL,evidence_json TEXT NOT NULL,digest TEXT NOT NULL,updated_at REAL NOT NULL);
CREATE TABLE IF NOT EXISTS backends(id TEXT PRIMARY KEY,state TEXT NOT NULL,evidence_json TEXT NOT NULL,digest TEXT NOT NULL,updated_at REAL NOT NULL);
CREATE TABLE IF NOT EXISTS missions(id TEXT PRIMARY KEY,name TEXT NOT NULL,kind TEXT NOT NULL,state TEXT NOT NULL,effect_class TEXT NOT NULL,definition_json TEXT NOT NULL,digest TEXT NOT NULL,updated_at REAL NOT NULL);
CREATE TABLE IF NOT EXISTS mission_runs(id TEXT PRIMARY KEY,mission_id TEXT NOT NULL,state TEXT NOT NULL,outcome_json TEXT NOT NULL,digest TEXT NOT NULL,started_at REAL NOT NULL,completed_at REAL NOT NULL);
CREATE TABLE IF NOT EXISTS federated_receipts(source TEXT NOT NULL,receipt_id TEXT NOT NULL,digest TEXT NOT NULL,path TEXT,created_at REAL,state TEXT,kind TEXT,PRIMARY KEY(source,receipt_id));
CREATE TABLE IF NOT EXISTS graph_versions(id TEXT PRIMARY KEY,node_count INTEGER NOT NULL,edge_count INTEGER NOT NULL,digest TEXT NOT NULL,path TEXT NOT NULL,created_at REAL NOT NULL);
CREATE TABLE IF NOT EXISTS sparse_snapshots(id TEXT PRIMARY KEY,file_count INTEGER NOT NULL,total_bytes INTEGER NOT NULL,chunk_count INTEGER NOT NULL,digest TEXT NOT NULL,path TEXT NOT NULL,created_at REAL NOT NULL);
